
:root{
  --bg:#02141d;--panel:#07364e;--panel2:#052a3c;--blue:#168bcf;
  --cyan:#6ee0ff;--green:#41d47f;--amber:#ffc857;--red:#ef5757;
  --muted:#a8bec9;--line:#ffffff22;
}
*{box-sizing:border-box}
body{margin:0;background:#011018;color:#fff;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
.app{max-width:1200px;margin:auto;min-height:100vh;background:linear-gradient(#07354d,#02141d)}
.windIndicator{display:none;position:absolute;left:12px;top:12px;z-index:6;background:#052a3ee8;border:1px solid #6ee0ff66;border-radius:12px;padding:8px 10px;min-width:180px;box-shadow:0 4px 14px #0005}
.windIndicator.show{display:block}.windArrow{font-size:25px;font-weight:900;color:#6ee0ff;line-height:1}.windText{font-size:10px;color:#d7f5ff;font-weight:800;letter-spacing:.05em;margin-top:3px}.windSub{font-size:9px;color:#a8bec9;margin-top:2px}

header{padding:13px 18px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;position:sticky;top:0;background:#052a3eee;backdrop-filter:blur(10px);z-index:20}
.brand{font-weight:900;letter-spacing:.17em}.ver{font-size:11px;color:var(--cyan)}
#hdrMode{font-weight:900;letter-spacing:.08em}#hdrMode.backBtn{cursor:pointer;background:#16475e;border:1px solid #6ee0ff55;border-radius:9px;padding:9px 13px;color:#fff;user-select:none}#hdrMode.backBtn:hover{background:#168bcf}#hdrMode.backBtn:active{transform:translateY(1px)}
.wrap{padding:15px}.screen{display:none}.screen.active{display:block}
.hero{height:240px;border-radius:20px;background:linear-gradient(#0013,#001d),url("../assets/embedded/pw-asset-001-0584ca491e.jpg") center/cover;display:flex;align-items:flex-end;padding:22px;box-shadow:0 20px 45px #0006}
.hero h1{margin:4px 0;font-size:34px}.hero .strap{font-size:14px;color:#d7e7ee}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:17px;padding:14px;margin-top:12px}
.panel h2,.panel h3{margin-top:0}
button{border:0;border-radius:11px;padding:12px 14px;background:var(--blue);color:#fff;font-weight:800;font-size:14px;cursor:pointer}
button.alt{background:#16475e}button.danger{background:#8e3535}
.big{width:100%;font-size:17px;padding:15px;margin-top:14px}
.conditions{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:14px}
.cond,.metric{background:var(--panel2);padding:10px;border-radius:11px}
.cond small,.metric small{display:block;color:var(--muted);font-size:10px}.cond b,.metric b{font-size:17px}
.layout{display:grid;gap:12px}.sea{height:440px;border-radius:16px;position:relative;overflow:hidden;background:repeating-radial-gradient(circle,#001a10 0 1px,#002819 2px 72px)}
svg{width:100%;height:100%}.own{fill:#fff}.tgt{fill:#ff655f}.ot{fill:none;stroke:#fff;stroke-width:.034}.tt{fill:none;stroke:#ff655f;stroke-width:.034}.ghost{fill:none;stroke:#ffc857;stroke-width:.035;stroke-dasharray:.12 .08}
.controls,.helm,.throttle,.tabs{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.controls button,.helm button,.throttle button,.tabs button{flex:1;min-width:68px}
.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}
.alert{display:none;position:absolute;z-index:5;left:10px;right:10px;top:10px;padding:13px;border-radius:11px;background:#9f1e1eee;border:2px solid #ff8d89;font-weight:900;text-align:center;font-size:18px;animation:pulse .7s infinite alternate}
@keyframes pulse{to{transform:scale(1.012);filter:brightness(1.2)}}
.note{color:var(--muted);font-size:12px;line-height:1.5}.status{font-size:20px;font-weight:900}.ok{color:var(--green)}.warn{color:var(--amber)}.bad{color:var(--red)}
.timeline{border-left:2px solid #ffffff22;padding-left:12px}.event{margin:9px 0}.event b{color:#fff}.event span{color:var(--muted)}
.debriefCard{background:#f6f8f9;color:#102a36;border-radius:16px;padding:16px;margin-top:12px}.debriefCard h3{margin-top:0}.tag{display:inline-block;background:#d7edf8;color:#0b4660;padding:5px 8px;border-radius:99px;font-size:11px;font-weight:800;margin:2px}
.rulebox{border-left:4px solid var(--blue);padding-left:12px;margin:12px 0}.rulebox b{display:block}
.score{font-size:42px;font-weight:900}.hidden{display:none}

.instrumentRow{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:10px}
.instrument{background:#041f2d;border:1px solid #ffffff18;border-radius:14px;padding:10px;text-align:center}
.dial{width:150px;height:76px;margin:2px auto 0;position:relative;overflow:hidden}
.arc{position:absolute;left:8px;right:8px;bottom:-67px;height:134px;border:12px solid #294e5f;border-top-color:#5bcdf5;border-radius:50%}
.pointer{position:absolute;left:50%;bottom:0;width:3px;height:66px;background:#fff;transform-origin:50% 100%;transform:rotate(0deg);transition:transform .12s linear}
.centerDot{position:absolute;left:calc(50% - 6px);bottom:0;width:12px;height:12px;border-radius:50%;background:#fff}
.scale{display:flex;justify-content:space-between;color:#a8bec9;font-size:10px;margin-top:-3px}
.bigread{font-size:23px;font-weight:900;margin-top:4px}
.subread{font-size:10px;color:#a8bec9;letter-spacing:.08em}

.modebar{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:10px 0}
.modebar button{width:100%;background:#16475e}
.modebar button.active{background:#168bcf;box-shadow:0 0 0 2px #7adfff55 inset}
.qualityAlert{display:none;position:absolute;z-index:6;left:10px;right:10px;bottom:10px;padding:13px;border-radius:11px;background:#7f3d05ee;border:2px solid #ffc857;color:#fff;font-weight:900;text-align:center;font-size:16px}
.qualityDetail{font-weight:600;font-size:12px;margin-top:4px;color:#ffe9bd}

.scenarios{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:10px}
.scenarioBtn{
 background:#07344a;text-align:left;padding:0;min-height:92px;overflow:hidden;
 display:grid;grid-template-columns:46% 54%;align-items:stretch;border:1px solid #ffffff12;
 border-radius:12px;position:relative
}
.scenarioBtn.active{background:#0b5274;box-shadow:0 0 0 2px #8ee7ff77 inset;border-color:#67dcff}
.scenarioBtn.active .scenarioPhoto img{filter:saturate(1.05) brightness(.93) contrast(1.05)}
.scenarioBtn:hover{border-color:#6ee0ff66}
.scenarioPhoto{position:relative;display:block;min-height:92px;overflow:hidden;background:#03131d}
.scenarioPhoto img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;filter:saturate(.96) brightness(.82) contrast(1.07)}
.scenarioBtn:hover .scenarioPhoto img{transform:scale(1.025);transition:.16s}
.scenarioPhotoShade{position:absolute;inset:0;background:linear-gradient(90deg,#00111a08,#00111a00 52%,#00111a9c)}
.scenarioCopy{padding:11px 12px;display:flex;flex-direction:column;justify-content:center;min-width:0}
.scenarioBtn b{display:block;font-size:13px;line-height:1.25}.scenarioBtn .scenarioCopy span{display:block;font-size:10px;color:#c6dce6;margin-top:5px;line-height:1.28}
.scenarioVisualTag{position:absolute;left:7px;bottom:6px;padding:3px 6px;border-radius:5px;background:#001722d9;border:1px solid #7be5ff55;color:#dff8ff;font-size:6.5px;font-weight:900;letter-spacing:.45px;z-index:4}
.scenarioVector{position:absolute;z-index:4;left:12%;right:12%;top:50%;height:2px;background:#ff5b5b;box-shadow:0 0 5px #0008;transform-origin:center}
.scenarioVector:after{content:"";position:absolute;right:-1px;top:-4px;border-left:8px solid #ff5b5b;border-top:5px solid transparent;border-bottom:5px solid transparent}
.scenarioVector.green{background:#2ce07c}.scenarioVector.green:after{border-left-color:#2ce07c}
.scenarioVector.crossA{transform:rotate(0deg)}.scenarioVector.crossB{transform:rotate(180deg)}
.scenarioVector.headA{left:8%;right:48%;transform:rotate(0)}.scenarioVector.headB{left:52%;right:8%;transform:rotate(180deg)}
.scenarioVector.overtake{top:68%;transform:rotate(-7deg)}.scenarioVector.deceptive{top:36%;transform:rotate(14deg)}
.scenarioVector.sailCross{top:62%;transform:rotate(-15deg)}
@media(max-width:760px){
 .scenarios{grid-template-columns:1fr}
 .scenarioBtn{grid-template-columns:42% 58%;min-height:88px}
 .scenarioPhoto{min-height:88px}
}
.scenarioMeta{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:10px}
.scenarioMeta div{background:#052a3c;border-radius:9px;padding:8px}.scenarioMeta small{display:block;color:#a8bec9;font-size:9px}.scenarioMeta b{font-size:12px}

.trainingDeck{margin-top:12px;background:#052a3c;border-radius:15px;padding:13px}
.markGrid{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.markCard{background:#041f2d;border:1px solid #ffffff18;border-radius:11px;padding:10px;min-height:112px}
.markCard b{display:block}.markCard small{color:#a8bec9}.markIcon{font-size:27px;line-height:1.2;margin-bottom:5px}
.quizQ{background:#041f2d;border-radius:12px;padding:12px;margin-top:8px}.quizOpts{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:8px}.quizOpts button{font-size:12px}.quizResult{margin-top:8px;font-weight:800}

.appMenu{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin:10px 0}
.appMenu button{min-height:58px;background:#06334a}.appMenu button.active{background:#168bcf}
.appPage{display:none}.appPage.active{display:block}
.ruleParts{display:grid;grid-template-columns:repeat(2,1fr);gap:7px;margin:10px 0}
.rulePart{background:#052a3c;border-radius:12px;padding:11px;cursor:pointer;border:1px solid #ffffff18}
.rulePart b{display:block}.rulePart small{color:#a8bec9}
.ruleList{display:grid;gap:6px}.ruleRow{background:#041f2d;border-radius:10px;padding:10px;border-left:3px solid #168bcf}
.ruleRow b{display:block}.ruleRow small{color:#b8ced8}
.moduleCards{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}
.moduleCard{background:#052a3c;border-radius:14px;padding:13px;min-height:110px}
.moduleCard h4{margin:0 0 6px}.tag{display:inline-block;background:#0b4059;border-radius:20px;padding:3px 7px;font-size:9px;margin:2px}

.ruleList{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}
.ruleRow{
  display:grid;grid-template-columns:62px 1fr 24px;align-items:center;gap:11px;
  min-height:82px;padding:9px 11px 9px 9px;border-left:0;
  border:1px solid #ffffff16;background:linear-gradient(135deg,#041f2d,#052a3c);
  overflow:hidden;position:relative;transition:transform .12s ease,border-color .12s ease,background .12s ease
}
.ruleRow:hover{transform:translateY(-1px);border-color:#6ee0ff66;background:linear-gradient(135deg,#06293a,#07364e)}
.ruleRow:active{transform:scale(.99)}
.ruleVisual{
  width:62px;height:62px;border-radius:14px;display:flex;align-items:center;justify-content:center;
  position:relative;background:radial-gradient(circle at 35% 30%,#0e5b78,#07283a 72%);
  border:1px solid #ffffff20;box-shadow:inset 0 0 18px #0003
}
.ruleVisual .rvIcon{font-size:28px;line-height:1;filter:drop-shadow(0 2px 2px #0007)}
.ruleVisual .rvNum{
  position:absolute;left:5px;top:4px;font-size:8px;font-weight:900;color:#bfefff;
  background:#001a27cc;border-radius:6px;padding:2px 4px;letter-spacing:.04em
}
.ruleText b{display:block;font-size:13px;line-height:1.25;margin-bottom:4px}
.ruleText small{display:block;color:#a8bec9;font-size:10px;line-height:1.25}
.ruleArrow{font-size:20px;color:#6ee0ff;text-align:right;opacity:.7}
.ruleRow[data-part="Part A"] .ruleVisual{background:radial-gradient(circle at 35% 30%,#205674,#092c40 72%)}
.ruleRow[data-part="Part B"] .ruleVisual{background:radial-gradient(circle at 35% 30%,#17614f,#092e32 72%)}
.ruleRow[data-part="Part C"] .ruleVisual{background:radial-gradient(circle at 35% 30%,#5b4d1d,#30280d 72%)}
.ruleRow[data-part="Part D"] .ruleVisual{background:radial-gradient(circle at 35% 30%,#5c315a,#2d1730 72%)}
.ruleRow[data-part="Part E"] .ruleVisual,.ruleRow[data-part="Part F"] .ruleVisual{background:radial-gradient(circle at 35% 30%,#4d4d62,#242434 72%)}
@media(max-width:720px){
 .ruleList{grid-template-columns:1fr}
 .ruleRow{min-height:76px;grid-template-columns:56px 1fr 20px}
 .ruleVisual{width:56px;height:56px}.ruleVisual .rvIcon{font-size:25px}
}

.annexGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:10px}
.annexCard{background:linear-gradient(145deg,#041f2d,#073248);border:1px solid #ffffff18;border-radius:16px;overflow:hidden;cursor:pointer;transition:.15s}
.annexCard:hover{border-color:#6ee0ff66;transform:translateY(-1px)}.annexCard:active{transform:scale(.99)}
.annexVisual{height:150px;position:relative;display:flex;align-items:center;justify-content:center;background:linear-gradient(180deg,#061a26,#03111a);overflow:hidden}
.annexVisual svg{width:100%;height:100%;display:block}
.annexVisual:after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#ffffff05,transparent 28%,transparent 72%,#0000001f)}
.annexCard{box-shadow:0 10px 28px #0003}
.annexCard:hover .annexVisual{filter:brightness(1.06)}
.annexBody{padding:12px}.annexBody h4{margin:0 0 6px;font-size:15px}.annexBody p{margin:6px 0 0;color:#b8ced8;font-size:11px;line-height:1.4}
.annexPills{display:flex;gap:5px;flex-wrap:wrap}.annexPill{font-size:9px;padding:3px 7px;border-radius:20px;background:#0b4059;color:#d7f5ff}
.annexArrow{float:right;color:#6ee0ff;font-size:20px}
.annexActions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.annexActions button{flex:1;min-width:190px}
@media(max-width:720px){.annexGrid{grid-template-columns:1fr}.annexVisual{height:105px}}

.annexPhoto{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;filter:saturate(.82) brightness(.58) contrast(1.08)}
.annexShade{position:absolute;inset:0;background:linear-gradient(90deg,#03121bd9 0%,#03121b33 48%,#03121b9e 100%)}
.annexPlateTitle{position:absolute;left:16px;top:13px;z-index:3;font-size:10px;font-weight:900;letter-spacing:1.2px;color:#8de8ff;text-shadow:0 2px 5px #000}
.annexPlateFooter{position:absolute;left:16px;right:16px;bottom:10px;z-index:3;display:flex;justify-content:space-between;gap:8px;color:#d5e7ee;font-size:7px;letter-spacing:.35px;text-shadow:0 2px 4px #000}
.photoLabel{position:absolute;z-index:4;padding:3px 6px;border-radius:5px;background:#001722d9;border:1px solid #7be5ff66;color:#e7f8ff;font-size:7px;font-weight:800;white-space:nowrap}
.navLamp{position:absolute;z-index:5;width:10px;height:10px;border-radius:50%;box-shadow:0 0 7px currentColor,0 0 16px currentColor;border:1px solid #fff9}
.navLamp.white{background:#fff;color:#fff}.navLamp.red{background:#ff3947;color:#ff3947}.navLamp.green{background:#20e77a;color:#20e77a}
.dayShapePanel{position:absolute;right:14px;top:34px;bottom:29px;width:78px;z-index:4;border-radius:8px;background:#eef4f5f2;border:1px solid #fff;box-shadow:0 4px 14px #0008;display:flex;align-items:center;justify-content:center;gap:8px}
.dayShapePanel:before{content:"DAY SHAPES";position:absolute;top:5px;left:0;right:0;text-align:center;color:#18313d;font-size:6px;font-weight:900;letter-spacing:.6px}
.dayBall{width:18px;height:18px;border-radius:50%;background:#050505;box-shadow:inset -3px -3px 4px #333}
.dayCone{width:0;height:0;border-left:10px solid transparent;border-right:10px solid transparent;border-bottom:20px solid #050505}
.photoEquipment{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:saturate(.92) brightness(.62) contrast(1.08)}
.equipTile{position:absolute;z-index:3;bottom:20px;padding:4px 7px;background:#001722dc;border:1px solid #ffffff33;border-radius:6px;color:#fff;font-size:7px;font-weight:900}
@media(max-width:720px){.dayShapePanel{width:65px}.annexPlateFooter{font-size:6px}}

.fishingVesselPhoto{
  object-position:center 68% !important;
  transform:scale(1.08);
  transform-origin:center 68%;
}

.ruleRow{grid-template-columns:92px 1fr 24px;min-height:86px}
.ruleVisual{
  width:92px;height:66px;border-radius:11px;overflow:hidden;position:relative;
  background:#041722;border:1px solid #ffffff24;box-shadow:inset 0 0 18px #0005,0 4px 12px #0003
}
.ruleVisual .rulePhoto{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;filter:saturate(.86) brightness(.68) contrast(1.08)}
.ruleVisual .rulePhotoShade{position:absolute;inset:0;background:linear-gradient(180deg,#00111a22,#00111a00 45%,#00111aa8)}
.ruleVisual .rvNum{z-index:3;left:5px;top:5px;color:#dff8ff;background:#001722e8;border:1px solid #6ee0ff55}
.ruleVisual .rvTag{position:absolute;z-index:3;left:5px;right:5px;bottom:4px;color:#fff;font-size:6.5px;font-weight:900;letter-spacing:.45px;text-shadow:0 1px 3px #000;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ruleRow:hover .rulePhoto{filter:saturate(.96) brightness(.78) contrast(1.08);transform:scale(1.025);transition:.18s}
@media(max-width:720px){
 .ruleRow{grid-template-columns:82px 1fr 20px}
 .ruleVisual{width:82px;height:60px}
 .ruleVisual .rvTag{font-size:6px}
}

.rulePhotoFallback{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:linear-gradient(145deg,#062b3b,#041923);color:#bfefff;text-align:center;padding:6px}
.rulePhotoFallback span{font-size:6px;letter-spacing:.7px;opacity:.7}.rulePhotoFallback b{font-size:8px;margin-top:3px}
.imageLicenceBtn{margin-top:10px;width:auto;background:#16475e;border:1px solid #6ee0ff44}
.creditSheet{display:none;position:fixed;inset:0;background:#001018e8;z-index:120;padding:18px;overflow:auto}
.creditSheet.open{display:block}.creditCard{max-width:900px;margin:22px auto;background:#07364e;border:1px solid #ffffff2a;border-radius:18px;padding:16px}
.creditRow{display:grid;grid-template-columns:1.2fr 1fr;gap:10px;background:#052a3c;border-radius:10px;padding:10px;margin-top:7px}
.creditRow b{display:block}.creditRow small{display:block;color:#a8bec9;margin-top:3px}.creditRow div:last-child{display:flex;gap:6px;align-items:center;justify-content:flex-end;flex-wrap:wrap;font-size:9px}
.creditRow span,.creditRow a{padding:3px 6px;border-radius:12px;background:#0b4059;color:#d7f5ff;text-decoration:none}
@media(max-width:720px){.creditRow{grid-template-columns:1fr}.creditRow div:last-child{justify-content:flex-start}}

.userVesselPhoto{width:150px;height:88px;flex:0 0 150px;background:#061923}
.userVesselPhoto img{width:100%;height:100%;object-fit:cover;object-position:center;filter:none}
#powerModeBtn .userVesselPhoto img{object-position:center 54%}
#sailModeBtn .userVesselPhoto img{object-position:center 52%}
.photographicVesselMode button{min-height:102px}
@media(max-width:760px){.userVesselPhoto{width:116px;height:72px;flex-basis:116px}.photographicVesselMode button{min-height:86px}}

.scenarioVector{display:none!important}
.scenarioGeometry{
 position:absolute;inset:5px 5px 5px 5px;z-index:4;pointer-events:none;
}
.scenarioGeometry svg{width:100%;height:100%;display:block;overflow:visible}
.sgOwn,.sgTarget{stroke:#00141d;stroke-width:1.4}
.sgOwn{fill:#e63d3d}.sgTarget{fill:#43d5c0}
.sgCourseOwn{stroke:#ff6262;stroke-width:1.8;stroke-dasharray:3 2}
.sgCourseTarget{stroke:#63ead7;stroke-width:1.8;stroke-dasharray:3 2}
.sgBearing{stroke:#dff8ff;stroke-width:.8;stroke-dasharray:2 2;opacity:.65}
.sgLabel{
 font:900 6.2px Arial,sans-serif;letter-spacing:.35px;
 paint-order:stroke;stroke:#001722;stroke-width:2px;stroke-linejoin:round;fill:#fff
}
.scenarioVisualTag{left:7px;bottom:6px}

.scenarioBtn{
  background:#07344a;text-align:left;padding:0;min-height:122px;overflow:hidden;
  display:grid;grid-template-columns:48% 52%;align-items:stretch;
  border:1px solid #ffffff16;border-radius:12px;position:relative
}
.scenarioBtn.active{
  background:#0b5274;box-shadow:0 0 0 2px #8ee7ff77 inset;border-color:#67dcff
}
.scenarioBtn:hover{border-color:#6ee0ff66}
.scenarioChart{
  position:relative;display:block;min-height:122px;overflow:hidden;
  background:
    linear-gradient(#6ea7bd22 1px,transparent 1px),
    linear-gradient(90deg,#6ea7bd22 1px,transparent 1px),
    linear-gradient(180deg,#e7dfc7,#d9d1b9);
  background-size:28px 28px,28px 28px,auto;
  border-right:1px solid #ffffff1c
}
.scenarioChart:before{
  content:"";position:absolute;left:12px;right:12px;top:50%;height:1px;background:#496c7844
}
.scenarioChart:after{
  content:"";position:absolute;top:10px;bottom:10px;left:50%;width:1px;background:#496c7844
}
.scenarioChart svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.scenarioCopy{padding:13px 14px;display:flex;flex-direction:column;justify-content:center;min-width:0}
.scenarioBtn b{display:block;font-size:15px;line-height:1.18;font-weight:900;letter-spacing:.02px}
.scenarioBtn .scenarioCopy span{display:block;font-size:10.5px;color:#cfe6ef;margin-top:6px;line-height:1.35;font-weight:700}
.scenarioChartTitle{
  position:absolute;left:8px;top:7px;z-index:5;padding:4px 7px;border-radius:6px;
  background:#f6f0dfed;border:1px solid #234a5c55;color:#183f50;font-size:7px;
  font-weight:900;letter-spacing:.55px
